execution.script:
pipeline {
    agent any

    tools {
        // Install the Maven version configured as "M3" and add it to the path.
        maven 'maven_lts'
    }
    stages {
        stage('inicializo') {
            steps {
                git 'https://github.com/jmagit/demos-devops.git'
            }
        }
        stage('compilo') {
            steps {
                sh "mvn compile"
            }
        }
        stage('test') {
            steps {
                sh 'mvn test'
            }
            post {
                always {
                    junit '**/target/surefire-reports/TEST-*.xml'
                    recordCoverage(tools: [[parser: 'JACOCO']])
                }
            }
        }
        stage("SonarQube Analysis") {
            steps {
                withSonarQubeEnv('SonarQubeDockerServer') {
                    sh 'mvn clean verify sonar:sonar'
                }
                timeout(2) { // time: 2 unit: 'MINUTES'
                  // In case of SonarQube failure or direct timeout exceed, stop Pipeline
                  waitForQualityGate abortPipeline: waitForQualityGate().status != 'OK'
                }
            }
        }

        stage('genera') {
            // when {
            //     branch 'production' 
            // }
            failFast true
            parallel {
                stage('empaqueta') {
                    steps {
                        sh 'mvn package -DskipTests'
                    }
                    post {
                        success {
                            archiveArtifacts artifacts: 'target/*.jar', fingerprint: true, followSymlinks: false
                        }
                    }
                }
                stage('documenta') {
                    steps {
                        sh 'mvn site'
                    }
                    post {
                        success {
                            publishHTML([
                                allowMissing: false, 
                                alwaysLinkToLastBuild: false, 
                                keepAll: false, 
                                reportDir: 'target/site/', 
                                reportFiles: 'index.html', 
                                reportName: 'Documentacion del sitio', 
                                reportTitles: 'Documentacion del sitio', 
                                useWrapperFileDirectly: true
                                ])
                        }
                    }
                }
            }
        }
        stage('despliega') {
            // when {
            //     branch 'production' 
            // }
            steps {
                mail to: 'amd@example.com',
                 subject: "Pendiente de aprobacion el depliege de ${currentBuild.fullDisplayName}",
                 body: "Para la aprobacion entre en ${env.BUILD_URL+'pipeline-overview'}"
                timeout(time: 3, unit: 'MINUTES') {
                    input cancel: 'Cancelar', message: 'Procedo al despliegue o aborto', ok: 'Aceptar'
                }
                sh 'mvn install -DskipTests'
            }
        }
    }
    post {
        success {
            mail to: 'team@example.com',
                 subject: "OK Pipeline: ${currentBuild.fullDisplayName}",
                 body: "Something in ${env.BUILD_URL}"
        }
        failure {
            mail to: 'team@example.com',
                 subject: "Failed Pipeline: ${currentBuild.fullDisplayName}",
                 body: "Something is wrong with ${env.BUILD_URL}"
        }
    }
}
